                if (vals[i] < 0) {
                    window.mySimulation.uiManager.showNotification(this._t('budget_negative'), 'warning');
                    return false;
                }
            }
            var total = vals[0] + vals[1] + vals[2] + vals[3] + vals[4];
            if (total > 1200) {
                window.mySimulation.uiManager.showNotification(this._t('budget_warning'), 'warning');
                return false;
            }
            if (total < 100) {
                window.mySimulation.uiManager.showNotification(this._t('budget_minimum'), 'warning');
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var r = this._computeRound(state);
            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);
            return r;
        }

        // Concave benefit of a budget line: doubling the spend does not double the effect.
        _lever(x) {
            return Math.sqrt(Math.max(0, x) / 100);
        }

        // Enterprise value (K): EBITDA x multiple. The multiple is set by IP quality and by what diligence finds.
        _ev(ds, discountPct) {
            var ebitda = 5320 + ds.licensingRevenue * 0.9;
            var multiple = 10 + (ds.portfolioHealth - 50) / 20 + (ds.competitiveMoat - 50) / 25 + (ds.ipValueScore - 50) / 25;
            if (ds.sepDeclared) multiple += 0.6;
            return Math.round(ebitda * Math.max(4, multiple) * (1 - (discountPct || 0) / 100));
        }

        _exposures(ds) {
            var ex = [];
            if (ds.litigationDrag > 0 || ds.trollMagnet > 0) ex.push('npe');
            if (ds.forkPending > 0 || ds.openSourced) ex.push('oss');
            if (ds.securitySpend < 900) ex.push('tradesecret');
            if (ds.spentTotal > ds.envelopeTotal + 300) ex.push('overrun');
            return ex;
        }

        _computeRound(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;

            var ivs = 0, cms = 0, phs = 0, lrr = 0, cost = 0, discount = 0;
            var key = '';

            // Status-quo drift: competitors file around the moat, patents age, the technology moves on.
            cms -= 4; phs -= 4; ivs -= 3;

            // Budget lines, with diminishing returns.
            var lit = this._lever(d.litigation), fil = this._lever(d.filing), lic = this._lever(d.licensing);
            var sec = this._lever(d.security), inn = this._lever(d.innovation);
            ivs += fil * 1.8 + inn * 1.2;
            cms += lit * 1.6 + fil * 0.7 + inn * 0.6;
            phs += sec * 1.6 + fil * 0.5 + lic * 0.4;
            lrr += lic * 34;
            if (d.litigation > 400) phs -= (d.litigation - 400) / 100 * 1.5;
            cost = d.litigation + d.filing + d.licensing + d.security + d.innovation;
            ds.securitySpend += d.security;

            // Delayed consequences carried by stocks from earlier rounds.
            if (ds.trollMagnet > 0 && round >= 2 && round <= 4) { phs -= 3; cms -= 1.5; cost += 120; }
            if (ds.litigationDrag > 0) { phs -= 4; cost += 150; ds.litigationDrag -= 1; if (ds.litigationDrag === 0) cms -= 4; }
            if (ds.forkPending > 0 && round === 3) { cms -= 7; lrr -= 40; ds.forkPending = 0; }
            if (ds.maintainAll && round >= 4) { cost += 34; ivs -= 3.5; }
            if (ds.prunedDividend > 0 && round >= 4) { ivs += 5; ds.prunedDividend -= 1; }
            if (ds.standardLost && round === 5) { cms -= 10; lrr -= 40; }

            if (round === 1) {
                if (d.strategy === 'litigate_npe') {
                    cost += 380; cms += 7; ivs += 1;
                    ds.litigationDrag = 2;
                    key = 'b_litigate';
                } else if (d.strategy === 'ipr_npe') {
                    cost += 140; cms += 3; ivs += 3; phs += 2;
                    ds.npeResolved = true;
                    key = 'b_ipr';
                } else if (d.strategy === 'license_npe') {
                    cost += 900; phs += 5; cms -= 1;
                    ds.npeResolved = true; ds.trollMagnet = 1;
                    key = 'b_license';
                } else if (d.strategy === 'buy_npe') {
                    cost += 1500; cms += 5; ivs += 4; phs += 2;
                    ds.npeResolved = true;
                    key = 'b_buy';
                }
            } else if (round === 2) {
                if (d.strategy === 'opensource_full') {
                    phs += 5; cms -= 5; ivs -= 3; lrr -= 60;
                    ds.openSourced = true;
                    key = 'b_os_full';
                } else if (d.strategy === 'opensource_community') {
                    cms += 2; phs += 3; ivs += 2; lrr += 60;
                    key = 'b_os_community';
                } else if (d.strategy === 'opensource_delay') {
                    phs += 1; ds.forkPending = 1;
                    key = 'b_os_delay';
                } else if (d.strategy === 'opensource_decline') {
                    cms += 2; ds.forkPending = 1;
                    key = 'b_os_decline';
                }
                lrr += 40;
            } else if (round === 3) {
                if (d.strategy === 'portfolio_maintain') {
                    cost += 74; phs += 4;
                    ds.maintainAll = true;
                    key = 'b_maintain';
                } else if (d.strategy === 'portfolio_lapse') {
                    ivs += 1; phs += 2; cost -= 34;
                    ds.prunedDividend = 2;
                    key = 'b_lapse';
                } else if (d.strategy === 'portfolio_challenge') {
                    cost += 50; cms += 4; ivs += 1;
                    key = 'b_challenge';
                } else if (d.strategy === 'portfolio_designaround') {
                    cost += 40; cms += 1; phs += 2; ivs += 1;
                    key = 'b_designaround';
                }
                lrr += 30;
            } else if (round === 4) {
                if (d.strategy === 'standards_sep') {
                    cms += 6; ivs += 5; phs += 1; lrr += 90;
                    ds.sepDeclared = true;
                    key = 'b_sep';
                } else if (d.strategy === 'standards_nosep') {
                    cms += 3; ivs += 2; lrr += 20;
                    key = 'b_nosep';
                } else if (d.strategy === 'standards_decline') {
                    phs += 2; cost -= 60;
                    ds.standardLost = true;
                    key = 'b_decline';
                } else if (d.strategy === 'standards_pledge') {
                    cms += 3; phs += 3; ivs += 2;
                    key = 'b_pledge';
                }
                lrr += 20;
            } else if (round === 5) {
                if (d.strategy === 'ma_full') {
                    cost += 200; phs += 6;
                    key = 'b_ma_full';
                } else if (d.strategy === 'ma_selective') {
                    cost += 80; phs += 4; discount += 4;
                    key = 'b_ma_selective';
                } else if (d.strategy === 'ma_reps') {
                    phs += 1; discount += 8;
                    key = 'b_ma_reps';
                } else if (d.strategy === 'ma_accept') {
                    phs -= 2; discount += 13;
                    key = 'b_ma_accept';
                }
            }

            ds.spentTotal += cost;
            ds.totalLegalCosts = ds.spentTotal;
            var over = Math.max(0, ds.spentTotal - ds.envelopeTotal);
            var prevOver = ds.overrunSeen || 0;
            if (over > prevOver) { phs -= (over - prevOver) / 100 * 1.2; cms -= (over - prevOver) / 100 * 0.6; }
            ds.overrunSeen = over;
            ds.ipBudget = Math.max(0, ds.envelopeTotal - ds.spentTotal);

            ds.ipValueScore = Math.round(Math.max(0, Math.min(100, ds.ipValueScore + ivs)) * 10) / 10;
            ds.competitiveMoat = Math.round(Math.max(0, Math.min(100, ds.competitiveMoat + cms)) * 10) / 10;
            ds.portfolioHealth = Math.round(Math.max(0, Math.min(100, ds.portfolioHealth + phs)) * 10) / 10;
            ds.licensingRevenue = Math.round(Math.max(0, ds.licensingRevenue + lrr));
            ds.totalLicensingIncome += ds.licensingRevenue;

            // Diligence at the exit: each open exposure is priced unless full remediation documented it.
            var ex = this._exposures(ds);
            if (round === 5) {
                var priced = ex.filter(function(e) { return !(d.strategy === 'ma_full' && (e === 'tradesecret' || e === 'oss')); });
                if (d.strategy === 'ma_selective') priced = priced.filter(function(e) { return e !== 'oss'; });
                discount += priced.length * 4;
                ds.diligenceExposures = priced;
                ds.diligenceDiscount = discount;
            }
            ds.enterpriseValue = this._ev(ds, round === 5 ? discount : 0);

            ds.choices = (ds.choices || []).slice(0, round - 1);
            ds.choices.push(d.strategy);
            ds.ivsHistory.push(ds.ipValueScore);
            ds.cmsHistory.push(ds.competitiveMoat);
            ds.phsHistory.push(ds.portfolioHealth);
            ds.lrrHistory.push(ds.licensingRevenue);
            ds.evHistory.push(ds.enterpriseValue);

            var sc = this._composite(ds, round);
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: sc.score, outcome: sc.outcome, process: sc.process });
            ds.performanceTier = this._tier(sc.score);

            return {
                period: round,
                strategy: d.strategy,
                strategyBonus: key,
                budgetUsed: Math.round(cost),
                ivsChange: Math.round(ivs * 10) / 10,
                cmsChange: Math.round(cms * 10) / 10,
                phsChange: Math.round(phs * 10) / 10,
                lrrChange: Math.round(lrr),
                ipValueScore: ds.ipValueScore,
                competitiveMoat: ds.competitiveMoat,
                portfolioHealth: ds.portfolioHealth,
                licensingRevenue: ds.licensingRevenue,
                enterpriseValue: ds.enterpriseValue,
                envelopeRemaining: ds.ipBudget,
                overallScore: sc.score,
                score: sc.score
            };
        }

        // One score function for the gradebook, the verdict and the debrief (0-100).
        // Outcome: the board's own targets (case: IVS 75, LRR 600K/yr, Moat floor 70) plus Portfolio Health.
        // Process: what an acquirer's diligence finds and whether the 6.2M envelope held.
        _composite(ds, round) {
            var band = function(x, lo, hi) { return Math.max(0, Math.min(100, (x - lo) / (hi - lo) * 100)); };
            var ivsP = band(ds.ipValueScore, 45, 85);
            var cmsP = band(ds.competitiveMoat, 50, 75);
            var phsP = band(ds.portfolioHealth, 55, 88);
            var lrrP = band(ds.licensingRevenue, 250, 750);
            var outcome = 0.32 * ivsP + 0.24 * cmsP + 0.24 * phsP + 0.20 * lrrP;
            var nEx = (round === 5 && ds.diligenceExposures) ? ds.diligenceExposures.length : this._exposures(ds).length;
            var dil = round === 5 ? Math.max(0, 100 - (ds.diligenceDiscount || 0) * 5) : Math.max(0, 100 - nEx * 15);
            var over = Math.max(0, ds.spentTotal - ds.envelopeTotal);
            var env = Math.max(0, 100 - over / 15);
            var process = 0.7 * dil + 0.3 * env;
            var score = Math.round(Math.max(0, Math.min(100, 0.7 * outcome + 0.3 * process)));
            return { score: score, outcome: Math.round(outcome), process: Math.round(process) };
        }

        _tier(score) {
            if (score >= 85) return 'master';
            if (score >= 72) return 'senior';
            if (score >= 58) return 'competent';
            return 'developing';
        }

        // Mistakes of this situation (TN 7 Q1-Q5), detected from what the student actually chose.
        _mistakes(ds) {
            var c = ds.choices || [];
            var m = [];
            if (c[0] === 'litigate_npe') m.push('m_litigate');
            if (c[0] === 'license_npe') m.push('m_settle');
            if (c[0] === 'buy_npe') m.push('m_buy');
            if (c[1] === 'opensource_full') m.push('m_os_full');
            if (c[1] === 'opensource_decline' || c[1] === 'opensource_delay') m.push('m_fork');
            if (c[2] === 'portfolio_maintain') m.push('m_maintain');
            if (c[3] === 'standards_decline') m.push('m_standard');
            if (c[4] === 'ma_accept' || c[4] === 'ma_reps') m.push('m_discount');
            if (ds.spentTotal > ds.envelopeTotal + 300) m.push('m_overrun');
            return m;
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var st = window.mySimulation && window.mySimulation.state;
            var ds = (st && st.domainState) || {};
            var last = history[history.length - 1].results || {};
            if (!ds.choices || !ds.choices.length) {
                ds = Object.assign({}, ds, { choices: history.map(function(h) { return (h.results || {}).strategy; }) });
            }
            var sc = (ds.performance && ds.performance.overallScore != null) ? ds.performance : { overallScore: last.overallScore || 0 };
            var score = sc.overallScore;
            var tier = this._tier(score);
            var t = this._t.bind(this);
            var insights = [];
            var mistakes = this._mistakes(ds);
            mistakes.forEach(function(k) { insights.push(t(k)); });
            if (!mistakes.length) insights.push(t('i_clean'));
            if ((ds.ipValueScore || 0) >= 75) insights.push(t('i_ivs_target'));
            else insights.push(t('i_ivs_short'));
            if ((ds.licensingRevenue || 0) >= 600) insights.push(t('i_lrr_target'));
            else insights.push(t('i_lrr_short'));
            if ((ds.competitiveMoat || 0) < 70) insights.push(t('i_moat_floor'));
            insights = insights.slice(0, 5);
            return {
                totalScore: score,
                overallScore: score,
                composite: score,
                score: score,
                maxScore: 100,
                outcomeScore: sc.outcome,
                processScore: sc.process,
                enterpriseValue: last.enterpriseValue || ds.enterpriseValue || 0,
                ipValueScore: ds.ipValueScore,
                competitiveMoat: ds.competitiveMoat,
                portfolioHealth: ds.portfolioHealth,
                licensingRevenue: ds.licensingRevenue,
                diligenceDiscount: ds.diligenceDiscount || 0,
                spentTotal: ds.spentTotal,
                turningPoint: mistakes.length ? mistakes[0] : '',
                performance: tier,
                performanceKey: 'tier_' + tier,
                performanceLabel: t('tier_' + tier),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var t = this._t.bind(this);
            var esc = function(s) { return String(s == null ? '' : s).replace(/[&<>]/g, function(c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]; }); };
            var fmt = function(v, dec) { var l = (window.vcI18n && window.vcI18n._lang) || 'en'; return Number(v || 0).toLocaleString(l === 'es' ? 'es-ES' : 'en-US', { maximumFractionDigits: dec || 0, minimumFractionDigits: dec || 0 }); };
            var h = '<div class="ipfortress-cm">';
            h += '<div class="ipfortress-cm-score"><span class="ipfortress-cm-num">' + esc(summary.overallScore) + '</span>/100 · <strong>' + esc(summary.performanceLabel) + '</strong></div>';
            h += '<div class="ipfortress-cm-sub">' + esc(t('cm_outcome')) + ': ' + esc(summary.outcomeScore) + '/100 · ' + esc(t('cm_process')) + ': ' + esc(summary.processScore) + '/100</div>';
            h += '<ul class="ipfortress-cm-kpis">';
            h += '<li>' + esc(t('ivs_label')) + ': ' + fmt(summary.ipValueScore, 1) + '/100 (' + esc(t('cm_target')) + ' 75)</li>';
            h += '<li>' + esc(t('cms_label')) + ': ' + fmt(summary.competitiveMoat, 1) + '/100 (' + esc(t('cm_floor')) + ' 70)</li>';
            h += '<li>' + esc(t('phs_label')) + ': ' + fmt(summary.portfolioHealth, 1) + '/100</li>';
            h += '<li>' + esc(t('lrr_label')) + ': ' + fmt(summary.licensingRevenue) + 'K/' + esc(t('cm_year')) + ' (' + esc(t('cm_target')) + ' 600K)</li>';
            h += '<li>' + esc(t('ev_label')) + ': ' + fmt((summary.enterpriseValue || 0) / 1000, 1) + 'M · ' + esc(t('cm_discount')) + ' ' + fmt(summary.diligenceDiscount) + '%</li>';
            h += '<li>' + esc(t('cm_spent')) + ': ' + fmt(summary.spentTotal) + 'K / 6.200K</li>';
            h += '</ul>';
            if (summary.turningPoint) h += '<p class="ipfortress-cm-turn"><strong>' + esc(t('cm_turning')) + '</strong> ' + esc(t(summary.turningPoint)) + '</p>';
            h += '<h4>' + esc(t('cm_takeaways')) + '</h4><ul class="ipfortress-cm-list">';
            (summary.insights || []).forEach(function(s) { h += '<li>' + esc(s) + '</li>'; });
            h += '</ul><h4>' + esc(t('cm_questions')) + '</h4><ol class="ipfortress-cm-list"><li>' + esc(t('q1')) + '</li><li>' + esc(t('q2')) + '</li><li>' + esc(t('q3')) + '</li></ol></div>';
            return h;
        }

